+static const uint32_t SETTINGS_MAGIC = 0x584E504F; // "OPNX"
+
+/**
+ * \internal
+ * Compute the 16 bits CRC value (CCITT) of a settings store
+ *
+ * @param store
+ * @return uint16_t
+ */
+static inline uint16_t settings_crc16(const settings_store_t *store)
+{
+    settings_store_t tmp;
+    memcpy(&tmp, store, sizeof(settings_store_t));
+
+    tmp.header.crc = 0;
+    return crc_ccitt((void *)&tmp, tmp.header.length);
+}
+
+/**
+ * \internal
+ * Returns a valid settings_store_t filled with default settings
+ *
+ * @param store a pointer to an allocated settings_store_t
+ * @return 0 in case of success, negative error code otherwise
+ */
+static int default_settings_store(settings_store_t *store)
+{
+    if (!store)
+        return -EINVAL;
+
+    store->header.MAGIC = SETTINGS_MAGIC;
+    store->header.counter = 0;
+    store->header.length = sizeof(settings_store_t);
+    store->settings = default_settings;
+    store->header.crc = settings_crc16(store);
+    return 0;
+}
+
+/**
+ * \internal
+ * Update the device settings in a settings store, updating counter, length and
+ * CRC accordingly.
+ *
+ * @param settings pointer to the up-to-date settings
+ * @param store pointer to the store to update
+ * @return 0 if successful, negative error code otherwise
+ */
+static int update_settings_store(const settings_t *settings, settings_store_t *store)
+{
+    if (!settings || !store)
+        return -EINVAL;
+
+    store->header.counter++;
+    store->header.length = sizeof(settings_store_t);
+    store->settings = *settings;
+    store->header.crc = settings_crc16(store);
+    return 0;
+}
+
+/**
+ * \internal
+ * Checks the integrity of a settings store
+ *
+ * @param store pointer to the settings_store to check
